def transform(grid):
    h, w = len(grid), len(grid[0])
    # Bottom row encodes the recurring sequence, with zeros omitted.
    seq = [x for x in grid[-1] if x]
    out = [row[:] for row in grid]
    if not seq:
        return out
    for r, row in enumerate(grid[:-1]):
        for c, value in enumerate(row):
            if value and value in seq:
                offset = seq.index(value)
                start = c - offset
                for j, color in enumerate(seq):
                    if 0 <= start+j < w:
                        out[r][start+j] = color
    return out
