def transform(grid):
    h, w = len(grid), len(grid[0])
    templates = []
    # Each contiguous nonzero run in a multi-cell row is a pattern.
    for row in grid:
        run = []
        for value in row + [0]:
            if value:
                run.append(value)
            elif run:
                if len(run) > 1:
                    templates.append(run)
                run = []
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if sum(value != 0 for value in row) != 1:
            continue
        c = next(c for c, value in enumerate(row) if value)
        value = row[c]
        matches = [seq for seq in templates if value in seq]
        if not matches:
            continue
        # If a color occurs in multiple patterns, the least ambiguous pattern is intended.
        seq = min(matches, key=lambda s: sum(value in t for t in templates))
        start = c - seq.index(value)
        for j, color in enumerate(seq):
            if 0 <= start + j < w:
                out[r][start + j] = color
    return out
